{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Background Colorectal laterally spreading tumors (LSTs) larger than 20 mm are significant precursors to colorectal cancer. Endoscopic submucosal dissection (ESD) and endoscopic mucosal resection (EMR) are widely used treatments, but their comparative efficacy and safety remain controversial.",
      "reason": "The abstract describes the current state of knowledge (LSTs >20 mm are important precursors; ESD and EMR are widely used) and explicitly states an important uncertainty (their comparative efficacy and safety remain controversial)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review and meta-analysis aimed to compare ESD and EMR in terms of local recurrence, perforation, and delayed bleeding for colorectal LSTs > 20 mm.",
      "reason": "The abstract explicitly states the purpose of the review and thereby explains the need for conducting the review to resolve the controversy about comparative efficacy and safety."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No text in the provided evidence explains whether similar systematic reviews exist or justifies the need for this review as an update/replication; no previous reviews are cited or discussed."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not include any description of the proposed mechanism of action of the interventions (ESD or EMR)."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes is presented in the supplied evidence."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement of the review objective(s) or research question(s) using a question-formulation framework is present in the supplied evidence. The retrieved text describes methods, outcomes, and comparisons but does not contain an explicit objectives statement or framed research question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "A total of 111 duplicate records were excluded using EndNote. After removing reviews, meta-analyses, letters, editorials, case reports/series, and ineligible publications, eight studies were ultimately included (see PRISMA flowchart, Fig. 1). The analysis comprised 3024 patients: 1451 underwent ESD and 1573 received EMR (including 588 piecemeal EMR procedures).",
      "reason": "The planned comparison between interventions (ESD versus EMR) is clearly described (numbers of patients in each group and that outcomes compare ESD vs EMR are reported). However, the comparison is not explicitly framed using a PICO or similar question-formulation framework, so the requirement is only partially met."
    }
  ],
  "confidence": 75
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Study selection: Inclusion criteria: (1) Studies involving LSTs with lesions measuring > 20 mm; (2) Comparative studies reporting primary and secondary outcomes of ESD versus EMR. Exclusion criteria: (1) Studies including LSTs < 20 mm or other lesions preventing outcome extraction; (2) Reviews, meta-analyses, letters, editorials; (3) Case reports/series or studies with < 30 patients per ESD/EMR group; (4) Animal studies.",
      "reason": "The manuscript explicitly lists inclusion and exclusion criteria covering lesion size, study type (comparative), minimum sample size per group, and study designs excluded, which are study characteristics used to determine eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Multiple databases were searched from inception to 1 May 2025, to identify eligible studies.",
      "reason": "The review specifies the search time frame (dissemination year boundary) but does not report eligibility restrictions or criteria regarding language or publication/report status (e.g., unpublished data, gray literature)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information is provided distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Local recurrence (eight studies, n = 3024): Pooled recurrence rates: ESD 0.62% versus EMR 12.02%. OR 0.07 (95% CI 0.03-0.13; p < 0.01) ... Delayed bleeding (eight studies, n = 3024): Pooled rates: ESD 3.65% versus EMR 3.75%. ... Perforation (eight studies, n = 3024): Pooled rates: ESD 5.38% versus EMR 1.53%.",
      "reason": "The synthesis groups (ESD vs EMR) are specified and outcomes are reported for each comparison across the included studies, linking the groups to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "Inclusion criteria: (1) Studies involving LSTs with lesions measuring > 20 mm; ... Exclusion criteria: (3) Case reports/series or studies with < 30 patients per ESD/EMR group; (4) Animal studies.",
      "reason": "While notable restrictions are listed (e.g., lesion >20 mm, minimum 30 patients per group), the manuscript does not provide rationales explaining why these specific restrictions were imposed."
    }
  ],
  "confidence": "85"
}

